#pragma once
namespace hp {
// Small view on the existing account APIs; no credentials, provider or sync engine here.
inline constexpr char accountConnectScript[]=R"AC('use strict';
window.hpAccountConnect=(root,contacts=false)=>{
function qrButton(parent,provider){const b=document.createElement('button');b.type='button';b.textContent=provider==='apple'?'Home-Display auf dem Handy einrichten':'QR-Code fürs Handy';const canvas=document.createElement('canvas');canvas.hidden=true;canvas.style.cssText='max-width:100%;width:260px;image-rendering:pixelated';b.onclick=async()=>{try{const response=await hpWeb.fetch('/api/accounts/login/qr?provider='+encodeURIComponent(provider),{cache:'no-store'});if(!response.ok)throw Error(await response.text());const data=await response.json(),size=data.size;if(!Number.isInteger(size)||size<21||size>149||data.bits.length!==Math.ceil(size*size/4))throw Error('Ungültiger QR-Code');const scale=5;canvas.width=canvas.height=(size+8)*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#000';for(let i=0;i<size*size;i++)if((parseInt(data.bits[Math.floor(i/4)],16)>>(3-i%4))&1)ctx.fillRect((i%size+4)*scale,(Math.floor(i/size)+4)*scale,scale,scale);canvas.hidden=false;notice.textContent='Mit der Handykamera scannen. Falls ein Gerätecode angezeigt wird, diesen bei der Anmeldung eingeben.'}catch(e){canvas.hidden=true;notice.textContent=e.message}};parent.append(b,canvas)}
 let token='',active=false;const notice=document.createElement('p'),list=document.createElement('div');notice.setAttribute('role','status');
 const accountLink=document.createElement('a');accountLink.href='/accounts';accountLink.target='_blank';accountLink.rel='noopener';accountLink.textContent='Kontenverwaltung öffnen (iCloud / CalDAV und OAuth-Einrichtung)';root.append(accountLink,notice,list);
 async function get(){hpWeb.requireVisible();const response=await hpWeb.fetch('/api/accounts/login/status',{cache:'no-store'});if(!response.ok)throw Error('Kontenstatus nicht verfügbar. Anmeldung und PIN prüfen.');return response.json()}
 async function command(path,args){if(active)return;active=true;try{if(!token){const response=await hpWeb.fetch('/api/csrf');if(!response.ok)throw Error('Anmeldung erforderlich.');token=(await response.json()).token}const response=await hpWeb.fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-HP-CSRF':token},body:JSON.stringify(args)});if(!response.ok)throw Error(await response.text());notice.textContent='Angefordert. Bitte Anmeldung / Freigabe abschließen.';await refresh()}catch(e){notice.textContent=e.message}finally{active=false}}
 function button(parent,title,path,args){const b=document.createElement('button');b.type='button';b.textContent=title;b.onclick=()=>command(path,args);parent.append(b)}
 async function refresh(){try{const data=await get();list.replaceChildren();for(const account of data.accounts){const card=document.createElement('div'),title=document.createElement('h4'),state=document.createElement('p');title.textContent=account.provider==='google'?'Google':'Microsoft';state.textContent=(account.email?account.email+' · ':'')+account.message;card.append(title,state);if(account.code){const code=document.createElement('strong');code.textContent=account.code;card.append(code)}if(account.url){const url=new URL(account.url);if(url.protocol==='https:'){const link=document.createElement('a');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Offizielle Anmeldung öffnen';card.append(link)}}button(card,'Anmelden','/api/accounts/'+account.provider+'/start',{purpose:'identity'});if(!contacts&&account.provider==='google')button(card,'Kalender freigeben','/api/accounts/google/start',{purpose:'calendar'});list.append(card)}for(const account of data.registry){const card=document.createElement('div'),label=document.createElement('p');label.textContent=account.displayName+' · '+account.provider+' · '+(contacts?account.contactsMessage:account.message);card.append(label);if(contacts&&!account.phonebookEnabled)button(card,'Kontakte aktivieren','/api/accounts/enabled',{id:account.id,feature:'phonebook',enabled:true});if(account.enabled&&(!contacts||account.phonebookEnabled)){button(card,contacts?'Kontakte freigeben':'Kalender freigeben','/api/accounts/authorize',{id:account.id,capability:contacts?'Contacts':'Calendar'});button(card,'Synchronisieren','/accounts/action',{slot:Number(account.id.slice(8)),action:'sync'})}list.append(card)}notice.textContent=notice.textContent||'Konten bereit. Kontakte werden nur nach ausdrücklicher Aktivierung synchronisiert.'}catch(e){notice.textContent=e.message}}
 const dav=document.createElement('details');dav.open=new URLSearchParams(location.search).get('connect')==='icloud';const summary=document.createElement('summary');summary.textContent='iCloud / eigener CalDAV-Server';dav.append(summary);
 const instruction=document.createElement('p');instruction.textContent='App-Passwort über HTTPS speichern; leer lassen für bereits gespeicherte Zugangsdaten. Kein normales Apple-ID-Passwort verwenden.';dav.append(instruction);const appleHelp=document.createElement('a');appleHelp.href='https://account.apple.com/';appleHelp.target='_blank';appleHelp.rel='noopener noreferrer';appleHelp.textContent='App-Passwort bei Apple erstellen';dav.append(appleHelp);
 function input(title,node){const label=document.createElement('label');label.textContent=title;label.append(node);dav.append(label);return node}
 const provider=input('Anbieter',document.createElement('select'));provider.add(new Option('iCloud','icloud'));provider.add(new Option('Eigener CalDAV-Server','caldav'));
 const slot=input('Kontoplatz (vorhandene Zuordnung prüfen)',document.createElement('select'));slot.add(new Option('Bitte auswählen',''));for(let i=0;i<5;i++)slot.add(new Option(String(i+1),String(i)));
 const username=input('Apple-ID / Benutzername',document.createElement('input'));username.maxLength=254;
 const password=input('App-Passwort',document.createElement('input'));password.type='password';password.maxLength=192;password.autocomplete='new-password';password.disabled=location.protocol!=='https:';
 const server=input('HTTPS-Server (nur eigener CalDAV)',document.createElement('input'));server.maxLength=512;server.placeholder='https://server.example/dav/';
 const connect=document.createElement('button');connect.type='button';connect.textContent='Verbinden';connect.onclick=()=>{if(location.protocol!=='https:'){notice.textContent='Bitte HTTPS verwenden.';return}if(slot.value===''){notice.textContent='Bitte einen Kontoplatz auswählen.';return}const args={slot:Number(slot.value),username:username.value,serverUrl:provider.value==='caldav'?server.value:'',password:password.value};password.value='';command('/api/accounts/'+provider.value+'/connect',args)};dav.append(connect);root.append(dav);
 const quick=document.createElement('details'),quickTitle=document.createElement('summary');quickTitle.textContent='Anmeldung mit Handykamera';quick.append(quickTitle);const help=document.createElement('p');help.textContent='Google / Microsoft zuerst oben anmelden starten, dann den QR-Code öffnen. Apple: QR-Code öffnet die lokale Home-Display-Einrichtung auf dem Handy. Dort anmelden und iCloud-App-Passwort eingeben. Kein Apple-OAuth-Kalenderzugriff.';quick.append(help);for(const [name,id] of [['Google','google'],['Microsoft','microsoft'],['Apple / iCloud','apple']]){const card=document.createElement('div'),title=document.createElement('h4');title.textContent=name;card.append(title);qrButton(card,id);quick.append(card)}root.append(quick);
 const reload=document.createElement('button');reload.type='button';reload.textContent='Anmeldestatus aktualisieren';reload.onclick=refresh;root.append(reload);hpWeb.onResume(refresh);refresh();return {refresh};
};
)AC";
}
